@charset "utf-8";

/*--container--*/
.jspContainer {
    overflow: hidden;
    position: relative;
}

.jspPane {
    position: absolute;
}

.jspVerticalBar {
    position: absolute;
    top: 0;
    right: 0;
    width: 16px;
    height: 100%;
}

.jspHorizontalBar {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 16px;
}

.jspVerticalBar *,
.jspHorizontalBar * {
    margin: 0;
    padding: 0;
}

.jspCap {
    display: none;
}

.jspHorizontalBar .jspCap {
    float: left;
}

.jspTrack {
    background: #dde;
    position: relative;
}

.jspDrag {
    background: #ddd;
    position: relative;
    top: 0;
    left: 0;
    cursor: pointer;
}

.jspHorizontalBar .jspTrack,
.jspHorizontalBar .jspDrag {
    float: left;
    height: 100%;
}

.jspArrow {
    background: #50506d;
    text-indent: -20000px;
    display: block;
    cursor: pointer;
}

.jspArrow.jspDisabled {
    cursor: default;
    background: #80808d;
}

.jspVerticalBar .jspArrow {
    height: 16px;
}

.jspHorizontalBar .jspArrow {
    width: 16px;
    float: left;
    height: 100%;
}

.jspVerticalBar .jspArrow:focus {
    outline: none;
}

.jspCorner {
    background: #eeeef4;
    float: left;
    height: 100%;
}

* html .jspCorner {
    margin: 0 -3px 0 0;
}

.jspVerticalBar {
    width: 6px;
}

.jspDrag {
    background: #a99479;
    border-radius: 8px;
}

.jspTrack {
    background: #f5f5f5;
    border-radius: 8px;
}

.mCSB_scrollTools .mCSB_draggerRail {
    background: #ddd;
    width: 2px;
}

.mCSB_scrollTools .mCSB_dragger .mCSB_dragger_bar {
    width: 6px;
    background: #333;
}

@font-face {
    font-family: impact;
    src: url('fonts/impact.eot');
    src: url("fonts/impact-1.eot") format("embedded-opentype"), url("fonts/impact.woff") format("woff"), url("fonts/impact.bin") format("truetype"), url("fonts/impact.svg") format("svg");
}

@font-face {
    font-family: icon;
    src: url('fonts/iconfont.eot');
    src: url('fonts/iconfont-1.eot') format('embedded-opentype'), url('fonts/iconfont.woff') format('woff'), url('fonts/iconfont.bin') format('truetype'), url('fonts/iconfont.svg') format('svg');
}

/*--类--*/
.gray {
    -webkit-filter: grayscale(100%);
    filter: grayscale(100%);
    filter: gray;
}

.fl {
    float: left;
}

.fr {
    float: right;
}

/*.clearfix:after{content:"";clear:both;display:block;}*/
.footer_b {
    position: fixed;
    left: 0;
    bottom: 0;
    width: 100%;
}

.select {
    display: inline-block;
    width: 210px;
    height: 30px;
    line-height: 30px;
    color: #707070;
    position: relative;
    border: 1px solid #ddd;
    text-align: left;
    cursor: pointer;
}

.select:before {
    content: "";
    background: url(../image/arrow7.png) center center no-repeat;
    width: 21px;
    height: 12px;
    right: 10px;
    top: 50%;
    margin-top: -6px;
    position: absolute;
}

.select span {
    display: block;
    margin: 0 10px 0 10px;
}

.select ul {
    position: absolute;
    left: -1px;
    right: -1px;
    top: 100%;
    background: #f0f0f0;
    display: none;
}

.select li {
    padding: 0 20px;
    line-height: 40px;
}

.checkbox {
    cursor: pointer;
}

.checkbox i {
    display: inline-block;
    vertical-align: sub;
    width: 15px;
    height: 15px;
    text-align: center;
    border: 1px solid #fff;
    margin-right: 10px;
    line-height: 15px;
    font-size: 0;
}

.checkbox.ckd i:after {
    content: "";
    width: 5px;
    height: 5px;
    background: #fff;
    display: block;
    margin: 5px 5px 0;
}

.radio {
    cursor: pointer;
    margin-right: 45px;
}

.radio i {
    display: inline-block;
    vertical-align: sub;
    width: 15px;
    height: 15px;
    text-align: center;
    border: 1px solid #fff;
    margin-right: 10px;
    line-height: 15px;
    font-size: 0;
    border-radius: 100%;
}

.radio.ckd i:after {
    content: "";
    width: 5px;
    height: 5px;
    background: #fff;
    display: block;
    margin: 5px 5px 0;
    border-radius: 100%;
}

/*--layers--*/

.layer {
    background: rgba(0, 0, 0, 0.8);
    position: fixed;
    left: 0;
    top: 0;
    right: 0;
    bottom: 0;
    z-index: 10;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease-out 0s;
    display: -ms-flexbox;
    display: flex;
    -ms-flex-align: center;
    align-items: center;
    -ms-flex-pack: center;
    justify-content: center;
}

.layer.showdiv {
    opacity: 1;
    visibility: visible;
}

.layer .close {
    font-size: 60px;
    font-family: icon;
    position: absolute;
    right: 50px;
    top: 50px;
    width: 80px;
    height: 80px;
    text-align: center;
    line-height: 80px;
    cursor: pointer;
    color: #ccc;
}

.layer .search_box {
    height: 45px;
    line-height: 45px;
    width: 550px;
    display: -ms-flexbox;
    display: flex;
    transform: translateY(-50px);
    opacity: 0;
    margin-top: -100px;
}

.layer.showdiv .search_box {
    transform: none;
    transition: all 0.5s ease-out 0s;
    opacity: 1;
}

.layer .search_box .kw {
    background: #fff;
    box-shadow: 3px 3px 3px rgba(0, 0, 0, 0.5) inset;
    -ms-flex: 1;
    flex: 1;
    padding: 0 12px;
    font-size: 16px;
    -webkit-appearance: none;
    appearance: none;
    border-radius: 0;
}

.layer .search_box .ok {
    background: #94070a;
    color: #fff;
    width: 120px;
    text-align: center;
    font-size: 18px;
    cursor: pointer;
    -webkit-appearance: none;
    appearance: none;
    border-radius: 0;
}

.layer .picbox {
    width: 100%;
    height: 100%;
    text-align: center;
}

.layer .picbox:after {
    content: "";
    vertical-align: middle;
    height: 100%;
    display: inline-block;
}

.layer .picbox img {
    max-width: 80%;
    max-height: 80%;
    width: auto;
    height: auto;
}

.layer .picbox video {
    width: 1000px;
    height: auto;
    display: inline-block;
    vertical-align: middle;
}

.layer .leader_box {
    background: #fff;
    border-top: 3px solid #ca0d0d;
    width: 1100px;
    position: relative;
}

.layer .leader_box .inner {
    padding: 60px;
}

.layer .leader_box .close {
    color: #aaa;
    right: 0;
    top: 0;
    font-size: 30px;
}

.layer .leader_box .t {
    display: flex;
    align-items: center;
}

.layer .leader_box .pic {
    width: 160px;
}

.layer .leader_box .txt {
    margin-left: 50px;
}

.layer .leader_box .txt .h {
    font-size: 18px;
}

.layer .leader_box .txt .p {
    margin-top: 15px;
}

.layer .leader_box .txt .p span {
    margin-right: 30px;
}

.layer .leader_box .text {
    margin-top: 40px;
    max-height: 300px;
    overflow: hidden;
}

.layer .leader_box .mCSB_scrollTools .mCSB_dragger .mCSB_dragger_bar {
    background: #ca0d0d;
}

.layer .leader_box .text p {
    margin-top: 20px;
}

.layer .leader_box .text p:first-child {
    margin-top: 0px;
}

.share-box {
    display: inline-block;
    vertical-align: middle;
    text-align: center;
}

.share-box:after {
    content: '';
    display: table;
    clear: both;
}

.share-box .share-item {
    position: relative;
    float: left;
    border-radius: 50%;
    cursor: pointer;
}

.share-box a.share-item {
    margin: 0;
    padding-left: 0;
    height: auto;
    background-image: none;
    font-size: inherit;
    line-height: inherit;
}

.share-box .share-item:after {
    content: '';
    vertical-align: top;
    font-family: "icon" !important;
    font-style: normal;
    -webkit-font-smoothing: antialiased;
    -webkit-text-stroke-width: 0.2px;
    -moz-osx-font-smoothing: grayscale;
    display: inline-block;
    color: #fff !important;
}

.share-box .icon-wchat:after {
    content: '\e603';
    font-size: 1.05em;
    margin-top: 0.05em;
}

.share-box .icon-qq:after {
    content: '\e606';
}

.share-box .icon-qzone:after {
    content: '\e60a';
}

.share-box .icon-sinawb:after {
    content: '\e605';
}

.share-box .icon-txwb:after {
    content: '\e609';
}

.share-label {
    display: inline-block;
}

.share-item .code {
    position: absolute;
    bottom: 100%;
    left: 50%;
    margin-left: -70px;
    margin-bottom: 10px;
    margin-top: 15px;
    padding: 10px;
    width: 140px;
    background-color: #fff;
    border-radius: 3px;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.15);
    border-radius: 5px;
    box-sizing: border-box;
    visibility: hidden;
