    width: 0;
    height: 0;
    border: 8px solid transparent;
    font-size: 0;
    border-top-color: #fff;
}

.share-item .code > img {
    display: block;
    width: 100%;
}

.share-item:hover .code {
    visibility: visible;
    opacity: 1;
    transform: none;
}

.share-box a.share-item {
    margin-left: 3px;
    width: 32px;
    height: 32px;
    line-height: 32px;
    font-size: 20px;
}

.share-box a.share-item.icon-sinawb {
    font-size: 23px;
}

.share-box a.share-item:hover {
    opacity: 1;
    z-index: 1;
}

