  visibility: hidden;
  opacity: 0;
  transition: .35s ease;
}
.video-container.open {
  visibility:visible;
  opacity:1
}

.close-video {
  position: absolute;
  width: 40px;
  height: 40px;
  color: #fff;
  border: 1px solid;
  border-radius: 50%;
  right: 20px;
  top: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

